-- TalentFit — Job Portal / Recruitment System — schema + seed data
-- Import via phpMyAdmin, or: mysql -u root -h HOST -P PORT < schema.sql
--
-- NOTE on `applications` / `application_status_history`: those two tables'
-- seed rows are generated by `database/generate_applications.php`, which
-- calls the real `Core\MatchScoreCalculator` against the candidate/job data
-- seeded below and INSERTs the result — so every seeded match_score and
-- score_breakdown here is a genuine engine output, not hand-typed numbers.
-- Their CREATE TABLE statements are still here; scroll to the bottom for
-- how to (re)generate their data after importing this file.

CREATE DATABASE IF NOT EXISTS job_portal_recruitment_system CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE job_portal_recruitment_system;

-- ---------------------------------------------------------------------------
-- users: all three personas (Super Admin, Recruiter, Candidate) live in one
-- table, distinguished by `role`. `status`/`source` capture the three
-- onboarding paths from FEATURES.md — candidates are approved immediately on
-- self-registration (no institutional risk); recruiters land `pending` on
-- self-registration and need admin approval, or are created directly
-- `approved` via bulk Excel import / individual admin-add (already vetted).
-- ---------------------------------------------------------------------------
CREATE TABLE users (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    email VARCHAR(190) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NULL,
    role ENUM('admin', 'recruiter', 'candidate') NOT NULL,
    status ENUM('pending', 'approved', 'rejected', 'suspended') NOT NULL DEFAULT 'approved',
    source ENUM('seed', 'self_registered', 'bulk_import', 'admin_manual') NOT NULL DEFAULT 'self_registered',
    reset_token VARCHAR(64) NULL,
    reset_token_expires_at DATETIME NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------------
-- recruiter_profiles: 1:1 with users(role='recruiter'). This is also the
-- public company profile page's data (FEATURES.md "Public company profile").
-- ---------------------------------------------------------------------------
CREATE TABLE recruiter_profiles (
    user_id INT PRIMARY KEY,
    company_name VARCHAR(180) NOT NULL,
    company_description TEXT NULL,
    logo_path VARCHAR(255) NULL,
    website VARCHAR(255) NULL,
    work_email_domain VARCHAR(150) NULL,
    contact_name VARCHAR(150) NULL,
    contact_phone VARCHAR(30) NULL,
    CONSTRAINT fk_rp_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------------
-- candidate_profiles: 1:1 with users(role='candidate'). `open_to_work` is
-- what makes recruiter candidate-search meaningful (FEATURES.md) — visible
-- in that pool even without having applied anywhere. Profile-completeness
-- is computed on read (App\Models\CandidateProfile::completeness()), not
-- stored, since it's derived purely from which sections are filled.
-- ---------------------------------------------------------------------------
CREATE TABLE candidate_profiles (
    user_id INT PRIMARY KEY,
    headline VARCHAR(200) NULL,
    photo_path VARCHAR(255) NULL,
    resume_path VARCHAR(255) NULL,
    location VARCHAR(150) NULL,
    phone VARCHAR(30) NULL,
    open_to_work TINYINT(1) NOT NULL DEFAULT 1,
    CONSTRAINT fk_cp_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------------
-- candidate_experience / candidate_education: the profile-as-timeline model
-- (FEATURES.md) — replaces a flat self-reported years_experience field.
-- Core\MatchScoreCalculator::candidateYearsExperience() sums these entries'
-- real durations; candidateHighestEducationOrdinal() reads `level` here.
-- ---------------------------------------------------------------------------
CREATE TABLE candidate_experience (
    id INT AUTO_INCREMENT PRIMARY KEY,
    candidate_id INT NOT NULL,
    title VARCHAR(150) NOT NULL,
    company VARCHAR(150) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NULL,
    is_current TINYINT(1) NOT NULL DEFAULT 0,
    description TEXT NULL,
    CONSTRAINT fk_ce_candidate FOREIGN KEY (candidate_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE candidate_education (
    id INT AUTO_INCREMENT PRIMARY KEY,
    candidate_id INT NOT NULL,
    degree VARCHAR(150) NOT NULL,
    institution VARCHAR(150) NOT NULL,
    field VARCHAR(150) NULL,
    level ENUM('high_school', 'diploma', 'bachelor', 'master', 'phd') NOT NULL,
    year_completed YEAR NULL,
    CONSTRAINT fk_ced_candidate FOREIGN KEY (candidate_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------------
-- skills: the curated taxonomy (FEATURES.md "Skills taxonomy") — the only
-- source of skill values profiles/postings can reference, so "JS" and
-- "JavaScript" never fragment matching. Populated by seed + admin-approved
-- skill_requests below.
-- ---------------------------------------------------------------------------
CREATE TABLE skills (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(100) NOT NULL UNIQUE,
    category VARCHAR(80) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------------
-- skill_requests: recruiter-submitted new-skill requests, pending admin
-- approval before the skill becomes selectable (FEATURES.md).
-- ---------------------------------------------------------------------------
CREATE TABLE skill_requests (
    id INT AUTO_INCREMENT PRIMARY KEY,
    requested_by INT NOT NULL,
    name VARCHAR(100) NOT NULL,
    category VARCHAR(80) NOT NULL,
    status ENUM('pending', 'approved', 'rejected') NOT NULL DEFAULT 'pending',
    reviewed_by INT NULL,
    reviewed_at DATETIME NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_sr_user FOREIGN KEY (requested_by) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_sr_reviewer FOREIGN KEY (reviewed_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------------
-- candidate_skills / job_skills: the structured attributes that make an
-- objective match score possible (FEATURES.md "Applications & Match
-- Scoring") — proficiency/importance are ordinal, never free text.
-- ---------------------------------------------------------------------------
CREATE TABLE candidate_skills (
    candidate_id INT NOT NULL,
    skill_id INT NOT NULL,
    proficiency ENUM('beginner', 'intermediate', 'expert') NOT NULL,
    PRIMARY KEY (candidate_id, skill_id),
    CONSTRAINT fk_cs_candidate FOREIGN KEY (candidate_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_cs_skill FOREIGN KEY (skill_id) REFERENCES skills(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------------
-- jobs: `status` is the recruiter-controlled lifecycle (draft/open/closed);
-- `moderation_status` is the admin moderation overlay (FEATURES.md "admin
-- moderate job postings: approve/flag/remove") — kept separate so an admin
-- flagging a posting doesn't destroy the recruiter's own open/closed state.
-- ---------------------------------------------------------------------------
CREATE TABLE jobs (
    id INT AUTO_INCREMENT PRIMARY KEY,
    recruiter_id INT NOT NULL,
    title VARCHAR(180) NOT NULL,
    description TEXT NOT NULL,
    location VARCHAR(150) NOT NULL,
    job_type ENUM('full_time', 'part_time', 'internship', 'contract') NOT NULL DEFAULT 'full_time',
    min_years_experience DECIMAL(4,1) NOT NULL DEFAULT 0,
    min_education_level ENUM('high_school', 'diploma', 'bachelor', 'master', 'phd') NULL,
    status ENUM('draft', 'open', 'closed') NOT NULL DEFAULT 'open',
    moderation_status ENUM('active', 'flagged', 'removed') NOT NULL DEFAULT 'active',
    moderation_note VARCHAR(255) NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_jobs_recruiter FOREIGN KEY (recruiter_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE job_skills (
    id INT AUTO_INCREMENT PRIMARY KEY,
    job_id INT NOT NULL,
    skill_id INT NOT NULL,
    importance ENUM('must_have', 'nice_to_have') NOT NULL DEFAULT 'must_have',
    min_proficiency ENUM('beginner', 'intermediate', 'expert') NOT NULL DEFAULT 'beginner',
    UNIQUE KEY uniq_job_skill (job_id, skill_id),
    CONSTRAINT fk_js_job FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE,
    CONSTRAINT fk_js_skill FOREIGN KEY (skill_id) REFERENCES skills(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------------
-- applications: match_score/score_breakdown are a SNAPSHOT taken at the
-- moment of applying (FEATURES.md) — immutable evidence of fit at that time,
-- not a live recomputation that would silently drift if either side edits
-- their data afterward. See Core\MatchScoreCalculator + App\Models\Application.
-- ---------------------------------------------------------------------------
CREATE TABLE applications (
    id INT AUTO_INCREMENT PRIMARY KEY,
    job_id INT NOT NULL,
    candidate_id INT NOT NULL,
    status ENUM('applied', 'shortlisted', 'interview', 'offered', 'rejected', 'withdrawn') NOT NULL DEFAULT 'applied',
    match_score INT NOT NULL,
    score_breakdown JSON NOT NULL,
    applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uniq_job_candidate (job_id, candidate_id),
    CONSTRAINT fk_app_job FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE,
    CONSTRAINT fk_app_candidate FOREIGN KEY (candidate_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------------
-- application_status_history: every pipeline transition, audited
-- (FEATURES.md "Application status pipeline") — both sides see a timeline,
-- not just a current state.
-- ---------------------------------------------------------------------------
CREATE TABLE application_status_history (
    id INT AUTO_INCREMENT PRIMARY KEY,
    application_id INT NOT NULL,
    from_status VARCHAR(20) NULL,
    to_status VARCHAR(20) NOT NULL,
    changed_by INT NULL,
    note VARCHAR(500) NULL,
    changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_ash_app FOREIGN KEY (application_id) REFERENCES applications(id) ON DELETE CASCADE,
    CONSTRAINT fk_ash_user FOREIGN KEY (changed_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB;

-- ---------------------------------------------------------------------------
-- saved_jobs: candidate bookmarking, same join-table shape as project 1's
-- election_voters enrollment but for an unrelated reason (personal
-- bookmarking, not eligibility) — FEATURES.md "Save/Bookmark a job".
-- ---------------------------------------------------------------------------
CREATE TABLE saved_jobs (
    id INT AUTO_INCREMENT PRIMARY KEY,
    candidate_id INT NOT NULL,
    job_id INT NOT NULL,
    saved_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uniq_candidate_job (candidate_id, job_id),
    CONSTRAINT fk_sj_candidate FOREIGN KEY (candidate_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT fk_sj_job FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE
) ENGINE=InnoDB;

